fn legacy_cli_catalog(file: &str, line: u32) -> Option<(&str, Cause)> {
    LEGACY_CLI_CATALOG
        .iter()
        .find(|(catalog_file, catalog_line, _, _)| *catalog_file == file && *catalog_line == line)
        .map(|(_, _, code, cause)| (*code, *cause))
}
